// Invocation-local real physical/Git DATA. Not a private compiler/source issuer.
import {execFileSync} from 'node:child_process';
import {constants,lstatSync,opendirSync,openSync,fstatSync,readSync,closeSync,mkdirSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';
const fail=message=>{throw TypeError('Compact sparse source Git IO: '+message);};
const keys=['dev','ino','mode','uid','gid','nlink','size','mtimeNs','ctimeNs'];
export const sameCompactPhysicalSourceStamp=(a,b)=>keys.every(key=>a[key]===b[key]);
export function compactSparseGit(root,args,{input,encoding='utf8',milliseconds=10000,maxBytes=67108864}={}){const empty=process.platform==='win32'?'NUL':'/dev/null',env={...Object.fromEntries(Object.entries(process.env).filter(([key])=>!key.startsWith('GIT_'))),GIT_CONFIG_NOSYSTEM:'1',GIT_CONFIG_GLOBAL:empty,GIT_CONFIG_SYSTEM:empty,GIT_LITERAL_PATHSPECS:'1',GIT_NO_LAZY_FETCH:'1',GIT_NO_REPLACE_OBJECTS:'1',GIT_AUTHOR_DATE:'2000-01-01T00:00:00Z',GIT_COMMITTER_DATE:'2000-01-01T00:00:00Z'};return execFileSync('git',['-c','core.hooksPath=/dev/null','-c','gc.auto=0','-c','maintenance.auto=false','-c','core.fsmonitor=false','-c','core.untrackedCache=false','-c','pack.threads=1','-c','pack.windowMemory=16m','-c','user.name=Router compiler source DATA','-c','user.email=compiler-data@example.invalid',...args],{cwd:root,env,input,encoding,timeout:milliseconds,maxBuffer:maxBytes,stdio:[input===undefined?'ignore':'pipe','pipe','pipe']});}
export function compactSparsePhysicalCensus(root,{retainBytes=false,maximum=67108864}={}){const files=[],directories=[],pending=[{path:root,name:'',depth:0}];let total=0;while(pending.length){const row=pending.pop(),stat=lstatSync(row.path,{bigint:true});if(!stat.isDirectory()||stat.isSymbolicLink()||row.depth>128||directories.length>=16384)fail('ordinary bounded source directory required');directories.push({path:row.path,name:row.name,stat});const directory=opendirSync(row.path);let failed=false;try{let entry;while((entry=directory.readSync())!==null){const path=join(row.path,entry.name),name=row.name?row.name+'/'+entry.name:entry.name,current=lstatSync(path,{bigint:true});if(current.isSymbolicLink())fail('physical source links refused');if(current.isDirectory())pending.push({path,name,depth:row.depth+1});else{if(!current.isFile()||current.size<0n||current.size>33554432n||files.length>=32768||(total+=Number(current.size))>maximum)fail('complete physical source census/bytes exceed bound');const file={path,name,stat:current};if(retainBytes)file.raw=readCompactSparsePhysicalFile(file);files.push(file);}}}catch(error){failed=true;throw error;}finally{try{directory.closeSync();}catch(error){if(!failed)throw error;}}if(!sameCompactPhysicalSourceStamp(stat,lstatSync(row.path,{bigint:true})))fail('physical directory changed during source census');}files.sort((a,b)=>a.name<b.name?-1:a.name>b.name?1:0);directories.sort((a,b)=>a.name<b.name?-1:a.name>b.name?1:0);return {root,files,directories,total};}
export function readCompactSparsePhysicalFile(row){const same=sameCompactPhysicalSourceStamp,before=lstatSync(row.path,{bigint:true});if(!before.isFile()||before.isSymbolicLink()||!same(row.stat,before)||before.size<0n||before.size>33554432n||!Number.isInteger(constants.O_NOFOLLOW)||constants.O_NOFOLLOW<=0||!Number.isInteger(constants.O_NONBLOCK)||constants.O_NONBLOCK<=0)fail('bounded ordinary precise no-follow source file required');const fd=openSync(row.path,constants.O_RDONLY|constants.O_NOFOLLOW|constants.O_NONBLOCK);let failed=false;try{if(!same(before,fstatSync(fd,{bigint:true})))fail('source replaced before open');const raw=Buffer.alloc(Number(before.size)+1);let at=0;while(at<raw.length){const count=readSync(fd,raw,at,Math.min(65536,raw.length-at),null);if(!count)break;at+=count;}if(at!==Number(before.size)||!same(before,fstatSync(fd,{bigint:true}))||!same(before,lstatSync(row.path,{bigint:true})))fail('complete source changed during read');return raw.subarray(0,at);}catch(error){failed=true;throw error;}finally{try{closeSync(fd);}catch(error){if(!failed)throw error;}}}
// Additive genuine FD range read. No NodeStats/source authority is synthesized.
// Full original path/file identity is checked even when only a range is read.
export function readCompactSparsePhysicalRange(row,offset,length){
 const same=sameCompactPhysicalSourceStamp,before=lstatSync(row.path,{bigint:true});if(!Number.isSafeInteger(offset)||offset<0||!Number.isSafeInteger(length)||length<0||length>33554432||!before.isFile()||before.isSymbolicLink()||!same(row.stat,before)||before.size<0n||before.size>33554432n||BigInt(offset)+BigInt(length)>before.size||!Number.isInteger(constants.O_NOFOLLOW)||constants.O_NOFOLLOW<=0||!Number.isInteger(constants.O_NONBLOCK)||constants.O_NONBLOCK<=0)fail('bounded exact no-follow physical source range required');const fd=openSync(row.path,constants.O_RDONLY|constants.O_NOFOLLOW|constants.O_NONBLOCK);let failed=false;
 try{if(!same(before,fstatSync(fd,{bigint:true})))fail('source range replaced before open');const raw=Buffer.alloc(length);let at=0;while(at<length){const count=readSync(fd,raw,at,Math.min(65536,length-at),offset+at);if(!count)break;at+=count;}if(at!==length||!same(before,fstatSync(fd,{bigint:true}))||!same(before,lstatSync(row.path,{bigint:true})))fail('source identity/bytes changed during complete range read');return raw;}catch(error){failed=true;throw error;}finally{try{closeSync(fd);}catch(error){if(!failed)throw error;}}
}

export function recloseCompactSparsePhysicalCensus(before){const same=sameCompactPhysicalSourceStamp;let failed=false,primary;const check=run=>{try{run();}catch(error){if(!failed){failed=true;primary=error;}}};for(const row of before.files)check(()=>{const raw=readCompactSparsePhysicalFile(row);if(!row.raw||!raw.equals(row.raw))fail('complete retained physical source bytes changed');});for(const row of before.directories)check(()=>{if(!same(row.stat,lstatSync(row.path,{bigint:true})))fail('complete physical directory identity changed');});check(()=>{const after=compactSparsePhysicalCensus(before.root);if(JSON.stringify(after.files.map(row=>row.name))!==JSON.stringify(before.files.map(row=>row.name))||JSON.stringify(after.directories.map(row=>row.name))!==JSON.stringify(before.directories.map(row=>row.name)))fail('complete physical source namespace changed');});if(failed)throw primary;}
export function releaseCompactSparsePhysicalCensus(before){if(!before)return;for(const row of before.files)row.raw=null;before.files.length=0;before.directories.length=0;}

export function writeCompactSparseHotPhysicalFile(root,name,raw,mode){let parent=root;for(const part of name.split('/').slice(0,-1)){parent=join(parent,part);try{mkdirSync(parent,{mode:0o700});}catch(error){if(error.code!=='EEXIST')throw error;}const stat=lstatSync(parent,{bigint:true});if(!stat.isDirectory()||stat.isSymbolicLink())fail('ordinary fresh hot-source ancestor required');}const path=join(root,name);if(!Number.isInteger(constants.O_NOFOLLOW)||constants.O_NOFOLLOW<=0)fail('positive no-follow hot source open required');const fd=openSync(path,constants.O_WRONLY|constants.O_CREAT|constants.O_EXCL|constants.O_NOFOLLOW,mode==='100755'?0o755:0o644);let failed=false,stat;try{writeFileSync(fd,raw);stat=fstatSync(fd,{bigint:true});if(((stat.mode&0o111n)?'100755':'100644')!==mode)fail('actual hot source mode differs');}catch(error){failed=true;throw error;}finally{try{closeSync(fd);}catch(error){if(!failed)throw error;}}if(!readCompactSparsePhysicalFile({path,stat}).equals(raw))fail('complete hot source raw bytes differ');}
